const searchParams = new URLSearchParams(document.currentScript.src.split('?')[1]);
const mbTssNonce = searchParams.get('nonce');
const mbTssRuleId = searchParams.get('ruleId');

const originalFunc = window.Notification.requestPermission;
console.debug('MBTSS_NOTIFICATION: Nonce: ', mbTssNonce, 'RuleId: ', mbTssRuleId);

window.Notification.requestPermission = function () {
    console.debug("TSS: Detected a suspicious permission request");
    let parameters = [].slice.call(arguments);
    window.top.postMessage(
        {
            type: "scam",
            subtype: "notificationLoop",
            ruleId: Number.parseInt(mbTssRuleId, 10),
            parameters: parameters,
            nonce: mbTssNonce,
        },
        window.location.origin
    );
    return originalFunc.apply(this, parameters);
};
